import React, { useState, useEffect } from 'react';
import { Routes, Route, useLocation, useNavigate, Navigate } from 'react-router-dom';

// Layout
import Sidebar from './Dashboard/Layout/Sidebar';
import TopBar from './Dashboard/Layout/TopBar';
import MobileMenu from './Dashboard/Layout/MobileMenu';

// Widgets - Seulement ceux qui existent
import DashboardHome from './Dashboard/Widgets/DashboardHome';
import UsersPage from './Dashboard/Widgets/UsersPage';
import ProductsPage from './Dashboard/Widgets/ProductsPage';
import OrdersPage from './Dashboard/Widgets/OrdersPage';
import AnalyticsPage from './Dashboard/Widgets/AnalyticsPage';
import MessagesPage from './Dashboard/Widgets/MessagesPage';
import SettingsPage from './Dashboard/Widgets/SettingsPage';

// Composants de base pour les routes secondaires (crées en temps réel)
const ReportsPage = () => (
  <div className="bg-white dark:bg-neutral-800 rounded-2xl shadow-lg p-6">
    <h1 className="text-2xl font-bold text-gray-800 dark:text-white mb-6">Rapports</h1>
    <p className="text-gray-600 dark:text-gray-300">
      Page des rapports - Contenu à implémenter
    </p>
  </div>
);

const CalendarPage = () => (
  <div className="bg-white dark:bg-neutral-800 rounded-2xl shadow-lg p-6">
    <h1 className="text-2xl font-bold text-gray-800 dark:text-white mb-6">Calendrier</h1>
    <p className="text-gray-600 dark:text-gray-300">
      Page du calendrier - Contenu à implémenter
    </p>
  </div>
);

const NotificationsPage = () => (
  <div className="bg-white dark:bg-neutral-800 rounded-2xl shadow-lg p-6">
    <h1 className="text-2xl font-bold text-gray-800 dark:text-white mb-6">Notifications</h1>
    <p className="text-gray-600 dark:text-gray-300">
      Page des notifications - Contenu à implémenter
    </p>
  </div>
);

const SystemPage = () => (
  <div className="bg-white dark:bg-neutral-800 rounded-2xl shadow-lg p-6">
    <h1 className="text-2xl font-bold text-gray-800 dark:text-white mb-6">Système</h1>
    <p className="text-gray-600 dark:text-gray-300">
      Page du système - Contenu à implémenter
    </p>
  </div>
);

const DatabasePage = () => (
  <div className="bg-white dark:bg-neutral-800 rounded-2xl shadow-lg p-6">
    <h1 className="text-2xl font-bold text-gray-800 dark:text-white mb-6">Base de données</h1>
    <p className="text-gray-600 dark:text-gray-300">
      Page de la base de données - Contenu à implémenter
    </p>
  </div>
);

const BackupPage = () => (
  <div className="bg-white dark:bg-neutral-800 rounded-2xl shadow-lg p-6">
    <h1 className="text-2xl font-bold text-gray-800 dark:text-white mb-6">Sauvegarde</h1>
    <p className="text-gray-600 dark:text-gray-300">
      Page de sauvegarde - Contenu à implémenter
    </p>
  </div>
);

const DashboardLayout = ({ onLogout }) => {
  const [sidebarOpen, setSidebarOpen] = useState(() => window.innerWidth >= 1024);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);

  const [notifications] = useState([
    { id: 1, title: 'New order received', message: 'Order #1234 from John Doe', time: '5 min ago', unread: true },
    { id: 2, title: 'Payment processed', message: 'Payment of $450 completed', time: '1 hour ago', unread: true },
    { id: 3, title: 'New user registered', message: 'Sarah Johnson joined the platform', time: '2 hours ago', unread: false },
  ]);

  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    const handleResize = () => {
      const mobile = window.innerWidth < 1024;
      setIsMobile(mobile);
      if (!mobile) setMobileMenuOpen(false);
    };

    window.addEventListener('resize', handleResize);
    handleResize();

    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleLogout = () => {
    if (onLogout) onLogout();
    navigate('/login');
  };

  const toggleSidebar = () => {
    if (isMobile) {
      setMobileMenuOpen(!mobileMenuOpen);
    } else {
      setSidebarOpen(!sidebarOpen);
    }
  };

  const closeMobileMenu = () => {
    setMobileMenuOpen(false);
  };

  // Récupérer le rôle utilisateur depuis le localStorage
  let role = 'user';
  try {
    const storedUser = typeof window !== 'undefined' ? localStorage.getItem('userData') : null;
    const parsedUser = storedUser ? JSON.parse(storedUser) : null;
    role = parsedUser?.role || localStorage.getItem('userRole') || 'user';
  } catch (err) {
    console.warn('Erreur lors de la récupération du rôle utilisateur :', err);
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-neutral-50 to-primary-50 dark:from-neutral-950 dark:to-primary-950">
      <Sidebar 
        sidebarOpen={isMobile ? mobileMenuOpen : sidebarOpen}
        location={location}
        onLogout={handleLogout}
        isMobile={isMobile}
        userRole={role}
      />

      <div className={`transition-all duration-300 ${isMobile ? '' : 'lg:pl-64'}`}>
        <TopBar 
          mobileMenuOpen={mobileMenuOpen}
          setMobileMenuOpen={setMobileMenuOpen}
          currentPath={location.pathname}
          notifications={notifications}
          toggleSidebar={toggleSidebar}
          isMobile={isMobile}
        />

        <main className="p-4 md:p-6">
          <Routes>
            {/* Redirection de /dashboard vers /dashboard/ */}
            <Route path="/" element={<Navigate to="/dashboard/" replace />} />

            {/* Page d'accueil du dashboard */}
            <Route index element={<DashboardHome userRole={role} />} />

            {/* Routes admin uniquement */}
            {role === 'admin' && (
              <>
                <Route path="users" element={<UsersPage />} />
                <Route path="products" element={<ProductsPage />} />
                <Route path="orders" element={<OrdersPage />} />
                <Route path="analytics" element={<AnalyticsPage />} />
                <Route path="reports" element={<ReportsPage />} />
                <Route path="calendar" element={<CalendarPage />} />
                <Route path="system" element={<SystemPage />} />
                <Route path="database" element={<DatabasePage />} />
                <Route path="backup" element={<BackupPage />} />
              </>
            )}

            {/* Routes accessibles aux deux rôles */}
            <Route path="messages" element={<MessagesPage />} />
            <Route path="settings" element={<SettingsPage userRole={role} />} />
            <Route path="notifications" element={<NotificationsPage />} />

            {/* Route 404 */}
            <Route path="*" element={
              <div className="flex flex-col items-center justify-center h-[60vh]">
                <h1 className="text-4xl font-bold text-gray-800 dark:text-white mb-4">404</h1>
                <p className="text-gray-600 dark:text-gray-300 mb-8">Page non trouvée</p>
                <button 
                  onClick={() => navigate('/dashboard')}
                  className="px-6 py-3 bg-primary-600 text-white rounded-lg hover:bg-primary-700 transition-colors"
                >
                  Retour au dashboard
                </button>
              </div>
            } />
          </Routes>
        </main>
      </div>

      <MobileMenu 
        mobileMenuOpen={mobileMenuOpen}
        setMobileMenuOpen={setMobileMenuOpen}
      />
    </div>
  );
};

export default DashboardLayout;
